/**
 * Invision Community
 * (c) Invision Power Services, Inc. - https://www.invisioncommunity.com
 *
 * ips.forum.flow.js - Flow filter controller
 *
 * Author: Matt Mecham, certainly not Rikki Tissier (yet)
 */
;( function($){
	"use strict";

	ips.controller.register('forums.front.forum.flow', {

		_ids: [],
		_button: null,
		_rootForum: null,
		urlParam: 'forumId',

		initialize: function () {
			this.on( 'click', '[data-node-id]', this.toggleFilters );
			this.on( 'click', '[data-action="dialogClose"]', this.closeFilterDialog );

			this.setup();
		},

		/**
		 * Um, set up...
		 */
		setup: function () {
			var self = this;

			/* Are we in a forum? */
			if ( this.scope.attr('data-rootForum') !== undefined ) {
				this._rootForum = this.scope.attr('data-rootForum');
			}

			if ( this._rootForum ) {
				this.urlParam = 'forumId' + this._rootForum;
			}

			/* Populate forum IDs */
			var _ids = ips.utils.url.getParam( this.urlParam );

			if ( _ids !== undefined ) {
				/* Check URL */
				this._ids = decodeURIComponent( _ids ).split(',');
			} else if ( this._rootForum ) {
				var found = false;
				if( ips.utils.cookie.get('forums_flowIdsRoots') !== undefined ) {
					/* Check local storage */
					try {
						var _jsonIds = JSON.parse(ips.utils.cookie.get('forums_flowIdsRoots'))[this._rootForum];
						found = true;
						if (_jsonIds !== undefined) {
							this._ids = _jsonIds;
						}
					} catch( exc ) { }
				}
				if ( ! found ) {
					this.scope.find('[data-node-id]').each(function (i, node) {
						var id = $(node).attr('data-node-id');
						self._ids.push(id);
					});
				}
			} else if( ips.utils.cookie.get('forums_flowIds') !== undefined ) {
				/* Check local storage */
				this._ids = ips.utils.cookie.get('forums_flowIds').split(',');
			}

			this._applyStoredFilters();

			/* Add forumIds to URL */
			if ( _ids === undefined && this._ids.length && this._rootForum === null ) {
				$( document ).trigger( 'updateTableURL', { [this.urlParam] : [...new Set( Object.values( this._ids ) )].join(',') } );
			}

			this._button = $('body').find("[data-ipsDialog-content='#elFluidFormFilters']");
			this._buttonText = $('body').find('[data-role="fluidForumMobileDesc"]');
			this._updateButtonText();
		},

		/**
		 * Applies selected styling for stored forum IDs (URL/cookie) without mutating _ids
		 *
		 * @returns {void}
		 */
		_applyStoredFilters: function () {
			if ( ! this._ids || ! this._ids.length ) {
				return;
			}

			var ids = Array.isArray( this._ids ) ? this._ids : Object.values( this._ids );
			ids = [...new Set( ids.map( String ).filter( Boolean ) )];
			this._ids = ids;

			var self = this;
			ids.forEach( function ( id ) {
				self.scope.find('[data-node-id="' + id + '"]').addClass('cForumMiniList__selected');
			});
		},

		/**
		 * Closes the mobile filter dialog
		 *
		 * @param	{event}	e	Event object
		 * @returns {void}
		 */
		closeFilterDialog: function (e) {
			e.preventDefault();
			var dialog = this.scope.closest('dialog.ipsDialog, .ipsDialog');

			if ( dialog.length ) {
				dialog.trigger('closeDialog');
			}
		},

		/**
		 * Event handler for toggling a filter
		 *
		 * @param 	{event} 	e 	Event object
		 * @returns {void}
		 */
		toggleFilters: function (e) {
			e.preventDefault();
			var link = $( e.currentTarget );
			var id = link.attr('data-node-id');
			var parentId = link.attr('data-parent-id');
			var hasChildren = link.attr('data-has-children');

			if ( ( this._ids ).indexOf( id ) == -1 ) {
				/* Does not exist, so add it */
				this.childSelect( id, false );

			} else {
				/* Exists, so remove it */
				this.childUnselect( id );
			}

			this._updateButtonText();

			$( document ).trigger( 'updateTableURL', { [this.urlParam]: [...new Set( Object.values( this._ids ) )].join(',') } );
		},

		/**
		 * Is item selected
		 *
		 */
		isSelected: function(id) {
			return this.scope.find('[data-node-id="' + id + '"]').hasClass('cForumMiniList__selected') ? true : false;
		},

		/**
		 * Select a child
		 *
		 */
		childSelect: function(id, skipChildren) {
			Debug.log("Select child: " + id );
			if ( ( this._ids ).indexOf( id ) == -1 ) {
				this._ids.push( id );
			}
			var node = this.scope.find('[data-node-id="' + id + '"]');
			node.addClass('cForumMiniList__selected');
			var parentId = node.attr('data-parent-id');

			/* Mark any children, but we do not need to keep individual row markings */
			if (skipChildren === false && (node.attr('data-has-children') || id == parentId)) {
				var self = this;
				for (const [k, v] of this.scope.find('[data-parent-id="' + id + '"]').toArray().entries()) {
					var _cId = $(v).attr('data-node-id');
					if (_cId != id) {
						self.childSelect(_cId, false);
					}
				};
			}

			this.updateCookie();
		},

		/**
		 * Unselect a child
		 *
		 */
		childUnselect: function(id) {
			Debug.log("UNselect child: " + id );
			/* Remove marking */
			this.scope.find('[data-node-id="' + id + '"]').removeClass('cForumMiniList__selected');

			/* Remove from local storage and id stack */
			this._ids = this._ids.filter(item => item !== id);
			this.updateCookie();

			/* Check for children of this and unselect those too */
			if ( this._rootForum === null ) {
				var self = this;
				for (const [k, v] of (this.scope.find('[data-parent-id="' + id + '"]').toArray().entries())) {
					var _cId = $(v).attr('data-node-id');
					if (_cId != id) {
						self.childUnselect(_cId);
					}
				};

				/* And we always need to unselect the category */
				this.parentUnselect( this.scope.find('[data-node-id="' + id + '"]').closest('[data-category]').find('[data-node-id]').first().attr('data-node-id') );
			}
		},

		/**
		 * Select a parent
		 *
		 */
		parentSelect: function(parentId) {
			Debug.log("Select parent: " + parentId );
			/* Mark category and children as selected */
			this.scope.find('[data-node-id="' + parentId + '"]').addClass('cForumMiniList__selected');

			/* Remove children from the arrays as PHP handles this */
			if ( this._rootForum === null ) {
				var self = this;
				for (const [k, v] of (this.scope.find('[data-parent-id="' + parentId + '"]').toArray().entries())) {
					var _cId = $(v).attr('data-node-id');

					if (_cId != parentId) {
						self.childUnselect(_cId);
					}
				};
			} else {
				this.updateCookie();
			}
		},

		/**
		 * Unselect a parent
		 *
		 */
		parentUnselect: function(parentId) {
			Debug.log("UNselect parent: " + parentId );
			/* Unselect parent as marked */
			var node = this.scope.find('[data-node-id="' + parentId + '"]');
			node.removeClass('cForumMiniList__selected');

			this._ids = this._ids.filter(id => id !== parentId);
			this.updateCookie();

			/* Off up the tree we go */
			Debug.log( "Looking for parent ID " + node.attr('data-parent-id') );
			if ( this._rootForum === null ) {
				var self = this;
				for (const [k, v] of (this.scope.find('[data-node-id="' + node.attr('data-parent-id') + '"]').toArray().entries())) {
					var _cId = $(v).attr('data-node-id');
					if (_cId != parentId) {
						Debug.log("Found " + _cId);
						self.parentUnselect(_cId);
					}
				};
			}
		},

		/**
		 * Update the cookie
		 */
		updateCookie: function(id) {
			var cookie = [...new Set( Object.values( this._ids ) )].join(',');
			Debug.log("Updating cookie: " + cookie );

			if ( ! this._rootForum ) {
				ips.utils.cookie.set('forums_flowIds', cookie, true);
			} else {
				var _json = {};
				if ( ips.utils.cookie.get( 'forums_flowIdsRoots' ) !== undefined ) {
					_json = JSON.parse( ips.utils.cookie.get( 'forums_flowIdsRoots' ) );
				}
				_json[ this._rootForum ] = [...new Set( Object.values( this._ids ) )];
				ips.utils.cookie.set('forums_flowIdsRoots', JSON.stringify( _json ), true);
				Debug.log("Updating cookie: " + JSON.stringify( _json ) );
			}
		},

		/**
		 * Updates the mobile button text based on selected forums
		 *
		 * @param		{event}		e			The submit event
		 * @param		{element} 	elem 		The element this widget is being created on
		 * @returns		{void}
		 */
		_updateButtonText: function () {
			var blobs = this.scope.find('.cForumMiniList__blob');
			var selectedBlobRows = blobs.filter( function () {
				if( $( this ).closest('.cForumMiniList__selected').length ){
					return true;
				}
				return false;
			});
			var text = '', buttonClass = '';

			// If the counts are the same, we know we've selected all of them
			if( blobs.length == selectedBlobRows.length || selectedBlobRows.length === 0 ){
				text = ips.getString('topicsFromAllForums');
				buttonClass = 'ipsButton--inherit';
			} else {
				text = ips.pluralize( ips.getString( 'topicsFromXForums' ), selectedBlobRows.length );
				buttonClass = 'ipsButton--secondary';
			}

			this._buttonText.text( text );
			this._button.removeClass("ipsButton--inherit ipsButton--secondary").addClass(buttonClass);
		}
	});
}(jQuery));

/**
 * Invision Community
 * (c) Invision Power Services, Inc. - https://www.invisioncommunity.com
 *
 * ips.forum.forumList.js - Controller for a forum listing
 *
 * Author: Rikki Tissier
 */
;( function($, _){
	"use strict";

	ips.controller.register('forums.front.forum.forumList', {

		/**
		* Initializes the controller
		 *
		* @returns {void}
		*/
		initialize() {
			this.on( 'ips:toggleForumCategory', this.toggleCategory );
			this.setup();
		},

		/**
		 * Setup method
		 *
		 * Hides categories the user has already hidden
		 *
		 * @returns {void}
		 */
		setup() {
			let hiddenCategories = ips.utils.db.get( 'hiddenCategories' );

			if (hiddenCategories && typeof hiddenCategories === 'object' && !Array.isArray(hiddenCategories) && Object.keys(hiddenCategories).length) {
				Object.entries(hiddenCategories).forEach(([key, val]) => {		
					document.querySelector("[aria-controls='forum-category_" + key + "']")?.setAttribute('aria-expanded', 'false');
					document.getElementById('forum-category_' + key)?.setAttribute('hidden', '');
				});
			}
		},

		/**
		 * Event handler for storing toggle status
		 * Hidden categories are stored localDB
		 *
		 * @param 	{ipsUiHiddenToggleEvent} 	e 	Event object
		 *
		 * @returns {void}
		 */
		toggleCategory(e) {
			/* Get the category which triggered the event and its ID */
			const category = e.target;
			const categoryID = category.closest('[data-categoryID]')?.dataset.categoryid;

			if (!category || !categoryID) {
				Debug.warn(`The forum list got a category hidden toggle event but couldn't determine which category was toggled`);
				return;
			}

			if (e.detail.hidden) {
				ips.utils.db.set( 'hiddenCategories', categoryID, true );
			} else {
				ips.utils.db.remove( 'hiddenCategories', categoryID );
			}

		}
	});
}(jQuery));

/**
 * Invision Community
 * (c) Invision Power Services, Inc. - https://www.invisioncommunity.com
 *
 * ips.forum.forumPage.js - Forum page controller
 *
 * Author: Rikki Tissier
 */
;( function($){
	"use strict";

	ips.controller.register('forums.front.forum.forumPage', {

		initialize: function () {
			this.on( 'click', '[data-action="markForumRead"]', this.markForumRead );
		},

		/**
		 * Marks all topics in a forum table as read, triggering an event on the table
		 *
		 * @param 	{Event} 	e 	Event object
		 * @returns {void}
		 */
		markForumRead (e) {
			e.preventDefault();

			ips.ui.alert.show( {
				type: 'confirm',
				icon: 'question',
				message: ips.getString('markForumAsReadConfirm'),
				subText: '',
				callbacks: {
					ok: () => {
						const url = $(e.currentTarget).attr('href');

						ips.getAjax()( url, {
							showLoading: true,
							bypassRedirect: true
						})
							.done( () => {
								// Trigger event on the table to hide unread markets
								this.triggerOn( 'core.global.core.table', 'markTableRead' );

								// Hide the link we've just clicked
								ips.utils.anim.go( 'fadeOut', $( e.currentTarget ) );

								ips.ui.flashMsg.show( ips.getString('forumMarkedRead') );
							})
							.fail( function (jqXHR, textStatus, errorThrown) {
								window.location = url;
							});
					}
				}
			});
		}
	});
}(jQuery));

/**
 * Invision Community
 * (c) Invision Power Services, Inc. - https://www.invisioncommunity.com
 *
 * ips.forum.hovercard.js - Topic hovercard in forum view
 *
 * Author: Rikki Tissier
 */
;( function($){
	"use strict";

	ips.controller.register('forums.front.forum.hovercard', {

		initialize: function () {
			this.on( 'click', '[data-action="markTopicRead"]', this.markTopicRead );
		},

		/**
		 * Marks a topic read from inside a hovercard
		 *
		 * @param 	{event} 	e 	Event object
		 * @returns {void}
		 */
		markTopicRead: function (e) {
			e.preventDefault();

			// Ignore if we've already done this
			if( $( e.currentTarget ).attr('data-disabled') ){
				return;
			}

			// Trigger event for table to mark the row
			this.trigger( 'markTableRowRead', {
				tableID: 'topics',
				rowID: this.scope.attr('data-topicID')
			});

			// Let the user know
			ips.ui.flashMsg.show( ips.getString('topicMarkedRead') );

			// And do the actual request
			ips.getAjax()( $( e.currentTarget ).attr('href'), {
				bypassRedirect: true
			});

			// Hide the link
			$( e.currentTarget ).addClass('i-opacity_4').attr('data-disabled');
		}
	});
}(jQuery));

/**
 * Invision Community
 * (c) Invision Power Services, Inc. - https://www.invisioncommunity.com
 *
 * ips.forums.archiveRules.js - makes the progress bar increase as archive rules settings are changed
 *
 * Author: Mark Wade
 */
;( function($){
	"use strict";

	ips.controller.register('forums.admin.settings.archiveRules', {

		initialize: function () {
			this.on( 'change', 'input,select', this.changeField );
			this.on( 'nodeSelectedChanged', '.ipsSelectTree', this.changeField );
			this.on( 'tokenAdded', '[data-ipsAutocomplete]', this.changeField );
			this.on( 'tokenDeleted', '[data-ipsAutocomplete]', this.changeField );
			this.setup();
		},

		setup: function () {
			var currentPercentage = parseInt( this.scope.find('[data-role="percentage"]').text() );

			this.scope
				.find('.ipsProgress')
					.toggleClass('i-opacity_4', !currentPercentage );
		},

		/**
		 * Save the keywords
		 *
		 * @param 	{event} 	e 	Event object
		 * @returns {void}
		 */
		changeField: function (e) {			
			var form = $( e.currentTarget ).closest('form');
			var self = this;

			ips.getAjax()( form.attr('action') + '&getCount=1', {
				data: form.serialize(),
				type: 'post'
			}).done( function (response) {									

				var currentPercentage = parseInt( self.scope.find('[data-role="percentage"]').text() );

				self.scope
					.find('.ipsProgress')
						.toggleClass('i-opacity_4', !parseInt( response.percentage ) )
					.end()
					.find('[data-role="percentage"]')
						.text( response.percentage )
					.end()
					.find('[data-role="number"]')
						.text( response.count )
					.end()
					.find('[data-role="percentageBar"]')
						.animate( { 'width': response.percentage + '%' }, 'fast' );
			}).fail(function(err){
				// Nothing
			});
		},
	});
}(jQuery));

/**
 * Invision Community
 * (c) Invision Power Services, Inc. - https://www.invisioncommunity.com
 *
 * ips.topic.activity.js - Topic activity controller
 *
 * Author: Rikki Tissier
 */
;( function($){
	"use strict";

	ips.controller.register('forums.front.topic.activity', {

		initialize: function () {
            this.on('click', '[data-action="toggleOverview"]', this.toggleOverview );
        },

        toggleOverview: function (e) {
            this.scope.toggleClass('cTopicOverview--expanded');
        }
	});
}(jQuery));

/**
 * Invision Community
 * (c) Invision Power Services, Inc. - https://www.invisioncommunity.com
 *
 * ips.topic.reply.js - Topic reply controller for "Reply" button
 *
 * Author: Rikki Tissier
 */
;( function($){
	"use strict";

	ips.controller.register('forums.front.topic.reply', {

		initialize: function () {
			this.on( 'click', '[data-action="replyToTopic"]', this.replyToTopic );
		},

		/**
		 * Handles a click on the reply to topic button. Triggers an event caught by the main topic view controller.
		 *
		 * @param 	{event} 	e 	Event object
		 * @returns {void}
		 */
		replyToTopic: function (e) {
			e.preventDefault();
			$( document ).trigger( 'replyToTopic' );
		}
	});
}(jQuery));

/**
 * Invision Community
 * (c) Invision Power Services, Inc. - https://www.invisioncommunity.com
 *
 * ips.topic.solved.js - Topic view controller
 *
 * Author: Matthew Mecham
 */
;( function($){
	"use strict";

	ips.controller.register('forums.front.topic.solved', {

		initialize: function () {
			this.on( 'click', '[data-action="mailSolvedReminders"]', this.mailSolvedReminders );
		},

		/**		
		 * Toggle on email reminders to come back and mark replies as the solution
		 *
		 * @param 	{event} 	e 	Event object
		 * @returns {void}
		 */
		mailSolvedReminders: function (e) {
			e.preventDefault();
			var _self = this;

			// Load the content
			ips.getAjax()( ips.getSetting('baseURL') + 'index.php?app=core&module=system&controller=ajax&do=subscribeToSolved' )
				.done( function (response) {
					var elem = _self.scope.find('[data-action="mailSolvedReminders"]');

					ips.utils.anim.go( 'fadeOutDown', elem );
					ips.ui.flashMsg.show( response.message, { timeout: 5 } );
			});
		}
	});
}(jQuery));

/**
 * Invision Community
 * (c) Invision Power Services, Inc. - https://www.invisioncommunity.com
 *
 * ips.topic.view.js - Topic view controller
 *
 * Author: Rikki Tissier
 */
;( function($){
	"use strict";

	ips.controller.register('forums.front.topic.view', {

		initialize: function () {
			$( document ).on( 'replyToTopic', this.replyToTopic.bind(this) );
			this.on( 'paginationClicked', this.paginationClicked );
			this.on( 'click', '[data-action="showMoreActivity"]', this.showActivity );
			this.on( 'click', '[data-action="closeMoreActivity"]', this.hideActivity );
		},

		/**
		 * Hide any helpful filters on page one
		 *
		 * @param 	{event} 	e 		Event object
		 * @param 	{object} 	data	Data object
		 * @returns {void}
		 */
		paginationClicked: function ( e, data ) {
			document.getElementById('ipsTopicView').dataset.ipsTopicFirstPage = ( data.pageNo == 1 );
		},

		/**
		 * Opens up the activity box when placed under the first post
		 *
		 * @param 	{event} 	e 	Event object
		 * @returns {void}
		 */
		showActivity: function (e) {
			e.preventDefault();

			this.scope.find('[data-role="moreActivity"]').show();
			this.scope.find('[data-action="showMoreActivity"]').hide();
			this.scope.find('[data-action="closeMoreActivity"]').show();
		},

		/**
		 * Closes the activity box when placed under the first post
		 *
		 * @param 	{event} 	e 	Event object
		 * @returns {void}
		 */
		hideActivity: function (e) {
			e.preventDefault();

			this.scope.find('[data-role="moreActivity"]').hide();
			this.scope.find('[data-action="showMoreActivity"]').show();
			this.scope.find('[data-action="closeMoreActivity"]').hide();
		},

		/**
		 * Triggers the initialize event on the editor
		 *
		 * @param 	{event} 	e 	Event object
		 * @returns {void}
		 */
		replyToTopic: function (e) {
			ips.ui.editorv5.getObjWithInit( this.scope.find('[data-role="replyArea"] [data-ipsEditorv5]'), function(editor){
				editor.unminimize(function(){
					editor.focus();
				});
			} );
		}
	});
}(jQuery));
